using System.ComponentModel.DataAnnotations;using System.Data;using GestionTubos.Application.Interfaces;using GestionTubos.Domain.Entities;using GestionTubos.Domain.Enums;using GestionTubos.Infrastructure.Data;using GestionTubos.Shared;using GestionTubos.Shared.Operaciones;using Microsoft.EntityFrameworkCore;
namespace GestionTubos.Infrastructure.Services;
public sealed class IngresoClienteService(GestionTubosDbContext db,IUsuarioActual?actor=null)
{
 public async Task<IngresoClienteDto> Recibir(IngresoClienteCrearDto dto,string usuario,CancellationToken ct)
 {
  var errores=new List<ValidationResult>();if(!Validator.TryValidateObject(dto,new(dto),errores,true))throw new InvalidOperationException(errores.First().ErrorMessage);if(dto.TuboIds.Distinct().Count()!=dto.TuboIds.Count)throw new InvalidOperationException("Hay tubos repetidos.");
  await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);
  var cliente=await db.Clientes.SingleOrDefaultAsync(x=>x.Id==dto.ClienteId,ct)??throw new InvalidOperationException("Seleccioná un cliente activo.");
  if(!await db.Ubicaciones.AnyAsync(x=>x.Id==dto.UbicacionId&&x.EsInterna&&x.GasBateria==null,ct))throw new InvalidOperationException("Seleccioná una ubicación de stock en planta.");
  var tubos=await db.Tubos.Include(x=>x.Ubicacion).Include(x=>x.TipoGas).Include(x=>x.CapacidadTubo).Where(x=>dto.TuboIds.Contains(x.Id)).ToListAsync(ct);
  if(tubos.Count!=dto.TuboIds.Count||tubos.Any(t=>t.TipoPropietario!=TipoPropietarioTubo.Cliente||t.ClientePropietarioId!=dto.ClienteId))throw new InvalidOperationException("Todos los tubos deben estar vinculados al cliente seleccionado.");
  if(tubos.Any(t=>t.EstadoDisponibilidad!=EstadoDisponibilidad.EnPoderCliente&&!(t.EstadoDisponibilidad==EstadoDisponibilidad.Disponible&&t.Ubicacion.EsInterna&&t.Ubicacion.GasBateria==null))||await db.IngresosClientesDetalle.AnyAsync(x=>dto.TuboIds.Contains(x.TuboId)&&x.FechaRetiroUtc==null,ct))throw new InvalidOperationException("Algún tubo ya tiene un ingreso abierto o una operación en curso. Actualizá la lista.");
  var hoy=DateOnly.FromDateTime(HoraArgentina.Hoy);var ph=await db.PruebasHidraulicas.Where(x=>dto.TuboIds.Contains(x.TuboId)&&x.Aprobada&&x.FechaVencimiento>=hoy).Select(x=>x.TuboId).Distinct().ToListAsync(ct);
  var siguiente=(await db.IngresosClientes.MaxAsync(x=>(long?)x.Id,ct)??0)+1;
  var ingreso=new IngresoCliente{Numero=$"ING-{siguiente:000000}",ClienteId=cliente.Id,ClienteNombre=cliente.RazonSocial??$"{cliente.Apellido}, {cliente.Nombre}",DocumentoCliente=cliente.Tipo==(TipoCliente)2?$"CUIT: {cliente.CuitCuil??"Sin registrar"}":$"DNI: {cliente.Dni??"Sin registrar"}",UbicacionId=dto.UbicacionId,PersonaEntrega=dto.PersonaEntrega.Trim(),DocumentoEntrega=dto.DocumentoEntrega?.Trim(),Usuario=usuario,UsuarioId=actor?.Id??"Sistema",Observaciones=dto.Observaciones?.Trim()};
  foreach(var t in tubos){var anterior=$"Contenido={(int)t.EstadoContenido};Disponibilidad={(int)t.EstadoDisponibilidad};Ubicación={t.UbicacionId}";var origen=t.UbicacionId;ingreso.Detalles.Add(new(){TuboId=t.Id,Codigo=t.CodigoInterno,Gas=t.TipoGas.Nombre,Capacidad=$"{t.CapacidadTubo.Valor:0.##} {t.CapacidadTubo.Unidad}"});t.EstadoContenido=EstadoContenido.Vacio;t.EstadoDisponibilidad=t.EstadoFisico is EstadoFisico.Danado or EstadoFisico.Inutilizable?EstadoDisponibilidad.EnMantenimiento:ph.Contains(t.Id)?EstadoDisponibilidad.Disponible:EstadoDisponibilidad.PendienteInspeccion;t.UbicacionId=dto.UbicacionId;db.MovimientosCilindro.Add(new(){TuboId=t.Id,Tipo="Ingreso de tubo del cliente",ClienteId=cliente.Id,UbicacionOrigenId=origen,UbicacionDestinoId=t.UbicacionId,EstadoAnterior=anterior,EstadoPosterior=$"Contenido=2;Disponibilidad={(int)t.EstadoDisponibilidad};Ubicación={t.UbicacionId}",UsuarioResponsable=usuario,Observaciones=ingreso.Numero+" · Recepción para carga. Propietario conservado."});}
  db.IngresosClientes.Add(ingreso);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return (await Obtener(ingreso.Id,ct))!;
 }
 public async Task<IngresoClienteDto?> Obtener(long id,CancellationToken ct){var x=await db.IngresosClientes.IgnoreQueryFilters().AsNoTracking().Include(x=>x.Detalles).ThenInclude(x=>x.RemitoEntrega).SingleOrDefaultAsync(x=>x.Id==id,ct);if(x is null)return null;var ubicacion=await db.Ubicaciones.IgnoreQueryFilters().Where(u=>u.Id==x.UbicacionId).Select(u=>u.Nombre).SingleAsync(ct);return new(x.Id,x.Numero,x.ClienteId,x.ClienteNombre,x.DocumentoCliente,x.FechaUtc,ubicacion,x.PersonaEntrega,x.DocumentoEntrega,x.Usuario,x.Observaciones,x.Detalles.Select(d=>new IngresoClienteTuboDto(d.TuboId,d.Codigo,d.Gas,d.Capacidad,d.FechaRetiroUtc,d.RemitoEntrega?.Numero)).ToList());}
}
